widget.prelude:
class _M(int):
    count = 0

    def __mul__(self, other):
        _M.count += 1
        return _M(int.__mul__(int(self), int(other)))

    def __rmul__(self, other):
        _M.count += 1
        return _M(int.__mul__(int(other), int(self)))

    def __mod__(self, other):
        return _M(int.__mod__(int(self), int(other)))


def mults(fn, a, e, m):
    _M.count = 0
    r = fn(_M(a), e, m)
    return _M.count, int(r)

