def power_mod(a, e, m):
    result = 1 % m
    a %= m
    while e > 0:
        if e & 1:
            result = result * a % m
        a = a * a % m
        e >>= 1
    return result

def inverse_mod(a, p):
    if a % p == 0:
        raise ValueError("no inverse")
    return pow(a, p - 2, p)

